-- ===================================================
-- migration_175: 秋の全国交通安全運動（2026/9/21〜9/30）手札の集計
--
--   各乗務員が乗務日ごとに、3つの最重要取組み項目を 1/2/3 で自己評価して手札に記入。
--     項目1 = 法定速度30km/h厳守 / 項目2 = スマホ・カーナビ注視根絶 / 項目3 = 眠気を感じたら必ず停止
--     1 = 100%遵守した / 2 = 80%以上守れた / 3 = 出来なかった
--   回収した手札258枚（2026年10月5日 スキャン）を初期データとして投入する。
--   数字は手書きスキャンからのAI下読み、氏名は社員名簿と照合して紐づけ（不明10枚）。画面から修正可。
--   課長ミッション →「秋の全国交通安全運動（2026）集計」で表示。
-- ===================================================

CREATE TABLE IF NOT EXISTS autumn_safety_2026_people (
  person_key    TEXT PRIMARY KEY,        -- s<手札番号>
  emp_no        TEXT,                    -- 社員名簿に紐づいた社員番号（不明は NULL）
  emp_name      TEXT NOT NULL,           -- 社員名簿の氏名（不明は「不明」）
  written_name  TEXT,                    -- 手札に記入された氏名（読み取り）
  written_no    TEXT,                    -- 手札に記入された社員番号（読み取り）
  team          INTEGER,
  division      INTEGER,
  sheet_no      INTEGER,                 -- 回収した手札の並び順
  note          TEXT,                    -- 読み取り時の注記（取消線・紐づけ根拠など）
  updated_at    TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS autumn_safety_2026_entries (
  person_key  TEXT NOT NULL,
  day         INTEGER NOT NULL CHECK(day BETWEEN 21 AND 30),
  item        INTEGER NOT NULL CHECK(item BETWEEN 1 AND 3),
  value       INTEGER NOT NULL CHECK(value BETWEEN 1 AND 3),
  updated_at  TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  PRIMARY KEY (person_key, day, item)
);

CREATE INDEX IF NOT EXISTS idx_autumn_safety_2026_entries_day ON autumn_safety_2026_entries(day);

CREATE TABLE IF NOT EXISTS autumn_safety_2026_meta (
  key         TEXT PRIMARY KEY,
  value       TEXT NOT NULL,
  updated_at  TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);


【項目別】「眠気を感じたら必ず停止」は「1」が91.8%と最も高く、夏季運動から続けてきた居眠り防止の呼びかけが定着していることがうかがえます。一方「法定速度30km/h厳守」は「1」が63.3%にとどまり、「2（80%以上）」が34.9%と3項目で最も多くなりました。67名は全乗務日で速度を「2」としており、生活道路で30km/hを常に守ることの難しさを自覚している乗務員が多いと考えられます。「スマホ・カーナビ注視根絶」は「1」が75.0%で、両者の中間です。

【日別】記入が最も多かったのは「交通事故ゼロを目指す日」の9月30日（135乗務日）で、速度「1」の割合は68.1%と期間平均を上回りました。一方で「3（出来なかった）」も同日に計8件あり、繁忙日ほど自己評価が厳しくなる傾向も見られます。

【「3」の記入】「3」は13名・25乗務日・計37件。うち千村和也さん・佐原浄さんは3項目すべてに「3」を続けて記入しており、凡例（1=遵守）の取り違えの可能性があるため本人への確認をお願いします。それ以外の「3」は速度に集中しており（18件）、聞き取りの際は走行ルートと時間帯を確認し、生活道路での速度管理を個別に助言することを勧めます。

【事故】取込済みの事故データ上、期間中（9/21〜9/30）の事故は2件（いずれも9/23の物損・相手方からの接触／後突）で、速度・スマホ注視・居眠りを原因とする事故は0件でした。

【今後に向けて】速度の「2」が常態化している層に対しては、30km/h規制区間の具体的な場所（営業所周辺・駅前など）を示した周知が効果的と考えます。なお、氏名・社員番号が読み取れなかった手札が10枚あり、集計には「不明」として含めています。')
  ON CONFLICT(key) DO NOTHING;


